// Core tests: the 22 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. Every extra expected value below was computed by hand from the
// SPEC's rules; the 14 success fixtures were additionally re-derived
// independently with Python fractions.Fraction (0 mismatches) before
// this file was written — see HANDOFF.md.

import assert from "node:assert/strict";
import test from "node:test";
import {
  formatAmount,
  formatRate,
  isDraftShapeValid,
  run,
} from "../public/js/core/tax-included.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const singleBase = { mode: "single", basis: "net", amount: "10000", ratePercent: "5", lines: null };
const linesBase = (lines) => ({ mode: "lines", ratePercent: "5", basis: null, amount: null, lines });

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("worked anchors: net 100000 at 5% is tax 5000 / gross 105000; gross 100 at 5% is net 95 / tax 5", () => {
  assert.deepEqual(run({ ...singleBase, amount: "100000" }).result, {
    basis: "net",
    gross: 105000,
    mode: "single",
    net: 100000,
    ratePercent: "5",
    tax: 5000,
  });
  assert.deepEqual(run({ ...singleBase, basis: "gross", amount: "100" }).result, {
    basis: "gross",
    gross: 100,
    mode: "single",
    net: 95,
    ratePercent: "5",
    tax: 5,
  });
});

test("boundary: amount cap 999999999999 succeeds; 1000000000000 is RANGE", () => {
  // 999,999,999,999 x 5% = 49,999,999,999.95 -> half-up 50,000,000,000.
  const ok = run({ ...singleBase, amount: "999999999999" });
  assert.equal(ok.ok, true);
  assert.equal(ok.result.tax, 50000000000);
  assert.equal(ok.result.gross, 1049999999999);
  assert.deepEqual(errorOf({ ...singleBase, amount: "1000000000000" }), {
    code: "RANGE",
    field: "amount",
    row: null,
  });
});

test("boundary: rate 100 succeeds (tax equals net); 100.01 and 0.00 are RANGE; 0.01 is the smallest accepted rate", () => {
  const full = run({ ...singleBase, amount: "100", ratePercent: "100" });
  assert.equal(full.ok, true);
  assert.equal(full.result.tax, 100);
  assert.equal(full.result.gross, 200);
  assert.deepEqual(errorOf({ ...singleBase, ratePercent: "100.01" }), {
    code: "RANGE",
    field: "ratePercent",
    row: null,
  });
  assert.deepEqual(errorOf({ ...singleBase, ratePercent: "0.00" }), {
    code: "RANGE",
    field: "ratePercent",
    row: null,
  });
  const tiny = run({ ...singleBase, amount: "10000", ratePercent: "0.01" });
  assert.equal(tiny.ok, true);
  assert.equal(tiny.result.tax, 1);
});

test("rate grammar: leading forms are DECIMAL_FORMAT; leading zeros canonicalize", () => {
  for (const bad of [".5", "5.", " 5", "5 ", "+5", "5,5", "5.555", "five"]) {
    assert.deepEqual(errorOf({ ...singleBase, ratePercent: bad }), {
      code: "DECIMAL_FORMAT",
      field: "ratePercent",
      row: null,
    });
  }
  assert.equal(run({ ...singleBase, ratePercent: "05" }).result.ratePercent, "5");
  assert.equal(run({ ...singleBase, ratePercent: "5.00" }).result.ratePercent, "5");
  assert.equal(run({ ...singleBase, ratePercent: "0.10" }).result.ratePercent, "0.1");
  assert.equal(run({ ...singleBase, ratePercent: "8.25" }).result.ratePercent, "8.25");
});

test("mode checks: empty, enum, input limit, unpaired surrogate", () => {
  assert.deepEqual(errorOf({ ...singleBase, mode: "" }), {
    code: "EMPTY",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...singleBase, mode: "SINGLE" }), {
    code: "ENUM",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...singleBase, mode: "single-single-single" }), {
    code: "INPUT_LIMIT",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...singleBase, mode: "single\uD800" }), {
    code: "UNICODE",
    field: "mode",
    row: null,
  });
});

test("single-mode nulls: null basis is EMPTY basis; null amount is EMPTY amount", () => {
  assert.deepEqual(errorOf({ ...singleBase, basis: null }), {
    code: "EMPTY",
    field: "basis",
    row: null,
  });
  assert.deepEqual(errorOf({ ...singleBase, amount: null }), {
    code: "EMPTY",
    field: "amount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...singleBase, basis: "grosss" }), {
    code: "ENUM",
    field: "basis",
    row: null,
  });
});

test("amount grammar: decimals, commas, signs, spaces and exponents are INTEGER_FORMAT", () => {
  for (const bad of ["100.0", "1,000", "-100", "+100", " 100", "100 ", "1e5", "12a"]) {
    assert.deepEqual(errorOf({ ...singleBase, amount: bad }), {
      code: "INTEGER_FORMAT",
      field: "amount",
      row: null,
    });
  }
  // Leading zeros are accepted and parsed as the same integer.
  assert.equal(run({ ...singleBase, amount: "007" }).result.net, 7);
});

test("lines: 20 rows of 1 net tax 1, per-line sum 0, difference 1", () => {
  // Each line: 1 x 5% = 0.05 -> 0. Total: 20 x 5% = 1.00 -> 1.
  const rows = Array.from({ length: 20 }, () => ({ amount: "1" }));
  const outcome = run(linesBase(rows));
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.subtotalNet, 20);
  assert.equal(outcome.result.tax, 1);
  assert.equal(outcome.result.gross, 21);
  assert.equal(outcome.result.perLineTaxSum, 0);
  assert.equal(outcome.result.roundingDifference, 1);
});

test("lines: null lines is EMPTY; subtotal over the cap is RANGE on lines", () => {
  assert.deepEqual(errorOf({ ...linesBase(null) }), {
    code: "EMPTY",
    field: "lines",
    row: null,
  });
  assert.deepEqual(
    errorOf(linesBase([{ amount: "999999999999" }, { amount: "1" }])),
    { code: "RANGE", field: "lines", row: null },
  );
});

test("lines: per-row errors name the 1-based row", () => {
  assert.deepEqual(errorOf(linesBase([{ amount: "100" }, { amount: "" }])), {
    code: "EMPTY",
    field: "amount",
    row: 2,
  });
  assert.deepEqual(errorOf(linesBase([{ amount: "1000000000000" }])), {
    code: "RANGE",
    field: "amount",
    row: 1,
  });
  assert.deepEqual(errorOf(linesBase([{ amount: "10" }, { amount: "20" }, { amount: "3.5" }])), {
    code: "INTEGER_FORMAT",
    field: "amount",
    row: 3,
  });
});

test("lines mode ignores inactive single fields beyond capacity/unicode", () => {
  // A garbage basis in lines mode is ignored (only its capacity and
  // surrogate checks apply); the same holds for amount.
  const outcome = run(linesBase([{ amount: "100" }]));
  assert.equal(outcome.ok, true);
  const withGarbage = run({ ...linesBase([{ amount: "100" }]), basis: "nonsense", amount: "junk" });
  assert.equal(withGarbage.ok, true);
  assert.deepEqual(withGarbage.result, outcome.result);
});

test("single mode ignores a non-null lines value", () => {
  const outcome = run({ ...singleBase, lines: [{ amount: "999" }] });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.net, 10000);
});

test("triple invariant: net + tax = gross and lines subtotal + tax = gross", () => {
  const samples = [
    { ...singleBase, amount: "1" },
    { ...singleBase, amount: "9999", basis: "gross" },
    { ...singleBase, amount: "123456789", ratePercent: "8.25" },
    { ...singleBase, amount: "777", basis: "gross", ratePercent: "0.5" },
  ];
  for (const input of samples) {
    const { result } = run(input);
    assert.equal(result.net + result.tax, result.gross);
  }
  const linesOutcome = run(linesBase([{ amount: "7" }, { amount: "13" }, { amount: "999" }]));
  const { result } = linesOutcome;
  assert.equal(result.subtotalNet + result.tax, result.gross);
  assert.equal(
    result.lines.reduce((sum, line) => sum + line.net, 0),
    result.subtotalNet,
  );
  assert.equal(result.tax - result.perLineTaxSum, result.roundingDifference);
});

test("schema: missing key, extra key, wrong types, accessor, array, null, symbol key", () => {
  const { mode, ratePercent, basis, amount, lines } = singleBase;
  assert.deepEqual(errorOf({ mode, ratePercent, basis, amount }), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
  assert.deepEqual(errorOf({ ...singleBase, extra: "x" }), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
  assert.deepEqual(errorOf({ ...singleBase, amount: 100 }), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
  assert.deepEqual(errorOf({ ...singleBase, lines: "x" }), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
  assert.deepEqual(errorOf(linesBase([{ amount: "100", note: "x" }])), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
  assert.deepEqual(errorOf(linesBase([{ amount: 100 }])), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
  const withAccessor = { ...singleBase };
  Object.defineProperty(withAccessor, "amount", { get: () => "100", enumerable: true });
  assert.deepEqual(errorOf(withAccessor), { code: "SCHEMA", field: null, row: null });
  assert.deepEqual(errorOf([singleBase]), { code: "SCHEMA", field: null, row: null });
  assert.deepEqual(errorOf(null), { code: "SCHEMA", field: null, row: null });
  const withSymbol = { ...singleBase, [Symbol("s")]: "x" };
  assert.deepEqual(errorOf(withSymbol), { code: "SCHEMA", field: null, row: null });
  const protoInstance = Object.create({ amount: "100" });
  assert.deepEqual(errorOf(linesBase([protoInstance])), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
});

test("formatAmount groups thousands; formatRate canonicalizes hundredths", () => {
  assert.equal(formatAmount(0), "0");
  assert.equal(formatAmount(1000), "1,000");
  assert.equal(formatAmount(100000), "100,000");
  assert.equal(formatAmount(999999999999), "999,999,999,999");
  assert.equal(formatRate(500n), "5");
  assert.equal(formatRate(550n), "5.5");
  assert.equal(formatRate(1n), "0.01");
  assert.equal(formatRate(10n), "0.1");
  assert.equal(formatRate(10000n), "100");
  assert.equal(formatRate(825n), "8.25");
});

test("isDraftShapeValid accepts the defaults and rejects a wrong-typed draft", () => {
  assert.equal(isDraftShapeValid(singleBase), true);
  assert.equal(isDraftShapeValid(linesBase([{ amount: "5" }])), true);
  assert.equal(isDraftShapeValid({ ...singleBase, amount: 5 }), false);
  assert.equal(isDraftShapeValid({ ...singleBase, extra: 1 }), false);
});
